/*
 * The learner's Home, worked out here so the page only draws it (DBU-05).
 * Identity is the session's userId. Learners never see a Step that is not shared (SCOPE).
 * The plan's order IS the journey (no milestones):
 *  - up next: the first homework in plan order that is not approved, and the next booked
 *    live session that has not ended (its join link is the step's, else the plan's);
 *  - a step is complete when a live session is done, a homework approved, a check-in done;
 *  - progress is complete steps / shared steps.
 * A check-in (DBU-10) says how many minutes it takes, when it was sent or answered, and, while it
 * has no date because it follows a step not dated yet, that step's title (`afterTitle`, only when
 * that step is shared). It can be answered while it is 'sent'.
 * Times stay ISO (UTC). The page shows them in me.timezone (the learner's profile; the
 * page falls back to the browser's zone when it is empty).
 */
(async () => {
  try {
    const me = String(Inputs.userId || '');
    if (!me) throw new Error('no session user');
    const q = (c, where) => Noodl.Records.query(c, where, { limit: 1000, plain: true });

    const users = await q('_User', { objectId: { equalTo: me } });
    const user = users[0] || {};
    Outputs.me = { name: user.name || '', timezone: user.timezone || '' };

    const plans = await q('Plan', { learner: { equalTo: me } });
    const active = plans.filter((p) => p.status === 'active');
    if (active.length > 1) throw new Error('more than one active plan for ' + me);
    const byStart = plans.slice().sort((a, b) => String(b.startedOn).localeCompare(String(a.startedOn)));
    const plan = active[0] || byStart[0] || null;

    const rows = plan ? (await q('Step', { plan: { equalTo: plan.objectId } }))
      .filter((s) => s.learner === me && s.shared === true)
      .sort((a, b) => a.position - b.position) : [];
    const ids = new Set(rows.map((s) => s.objectId));
    const subs = rows.length ? (await q('Submission', { learner: { equalTo: me } })).filter((s) => ids.has(s.step)) : [];
    const answers = rows.some((s) => s.kind === 'checkin') ? (await q('CheckinResponse', { learner: { equalTo: me } })).filter((r) => ids.has(r.step)) : [];
    const lastHandIn = (stepId) => subs.filter((s) => s.step === stepId)
      .map((s) => s.createdAt).sort().pop() || null;

    const COMPLETE = { live: 'done', homework: 'approved', checkin: 'done' };
    const counts = { live: 0, homework: 0, checkin: 0 };
    const steps = rows.map((s) => {
      counts[s.kind] = (counts[s.kind] || 0) + 1;
      const minutes = Number.isInteger(s.durationMin) ? s.durationMin : 60;
      const start = s.startsAt ? Date.parse(s.startsAt) : NaN;
      const checkin = s.kind === 'checkin';
      const anchor = checkin && !s.sendsAt && s.sendAfter ? rows.find((x) => x.objectId === s.sendAfter.step) : null;
      const response = checkin ? answers.find((r) => r.step === s.objectId) : null;
      return {
        id: s.objectId,
        position: s.position,
        kind: s.kind,
        number: counts[s.kind],
        title: s.title || '',
        status: s.status,
        complete: COMPLETE[s.kind] === s.status,
        startsAt: s.startsAt || null,
        endsAt: isNaN(start) ? null : new Date(start + minutes * 60000).toISOString(),
        durationMin: minutes,
        dueAt: s.dueAt || null,
        sendsAt: s.sendsAt || null,
        prepNote: s.kind === 'live' ? (s.prepNote || '') : '',
        meetingLink: s.kind === 'live' ? (s.meetingLink || (plan && plan.meetingLink) || '') : '',
        handedInAt: s.kind === 'homework' ? lastHandIn(s.objectId) : null,
        minutesToAnswer: checkin ? (s.form && Number.isInteger(s.form.minutes) ? s.form.minutes : 2) : null,
        sentAt: checkin ? s.sentAt || null : null,
        answeredAt: response ? response.createdAt : null,
        afterTitle: anchor ? anchor.title || '' : '',
        answerable: checkin && s.status === 'sent'
      };
    });

    const now = Date.now();
    const homework = steps.find((s) => s.kind === 'homework' && s.status !== 'approved') || null;
    const live = steps
      .filter((s) => s.kind === 'live' && s.status === 'booked' && s.endsAt && Date.parse(s.endsAt) > now)
      .sort((a, b) => String(a.startsAt).localeCompare(String(b.startsAt)))[0] || null;
    const toBook = steps.find((s) => s.kind === 'live' && s.status === 'to_book') || null;
    steps.forEach((s) => { s.current = !!homework && s.id === homework.id; });

    const complete = steps.filter((s) => s.complete).length;
    const started = plan && plan.startedOn ? Date.parse(plan.startedOn) : NaN;
    Outputs.plan = plan ? {
      title: plan.title || '',
      status: plan.status,
      startedOn: plan.startedOn || null,
      week: isNaN(started) ? null : Math.max(1, Math.floor((now - started) / (7 * 86400000)) + 1)
    } : null;
    Outputs.steps = steps;
    Outputs.upNext = {
      homework,
      live,
      // Offered only when nothing is booked: a session still to book, and a link to book it.
      bookingLink: !live && toBook && plan && plan.bookingLink ? plan.bookingLink : ''
    };
    Outputs.progress = { complete, total: steps.length, percent: steps.length ? Math.round((complete * 100) / steps.length) : 0 };
    Outputs.counts = counts;
    Outputs.done();
  } catch (e) {
    console.error('[dbu:learnerHome]', String((e && e.message) || e));
    Outputs.failed();
  }
})();

/*
 * Home's "Latest from Richard" card (DBU-07): the newest message from the coach in my own
 * conversation, and how many of his I have not read. Runs after Home is worked out; reading
 * Home marks nothing read (only Messages and a homework's thread do).
 */
(async () => {
  try {
    const me = String(Inputs.userId || '');
    if (!me) throw new Error('no session user');
    const q = (c, where) => Noodl.Records.query(c, where, { limit: 1000, plain: true });
    const theirs = (await q('Message', { learner: { equalTo: me } }))
      .filter((m) => m.author !== me)
      .sort((a, b) => String(a.createdAt).localeCompare(String(b.createdAt)));
    const last = theirs[theirs.length - 1] || null;
    let stepTitle = '';
    if (last && last.step) {
      const steps = await q('Step', { objectId: { equalTo: last.step } });
      if (steps[0] && steps[0].learner === me && steps[0].shared === true) stepTitle = String(steps[0].title || '');
    }
    Outputs.latest = last ? { id: last.objectId, body: String(last.body || ''), at: last.createdAt, stepId: stepTitle ? last.step : '', stepTitle, isNew: !last.readAt } : null;
    Outputs.unread = theirs.filter((m) => !m.readAt).length;
    Outputs.done();
  } catch (e) {
    console.error('[dbu:learnerHome messages]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
